#!/usr/bin/env python3
"""Patch AndroidManifest generated by flutter create for microphone foreground service."""
from pathlib import Path
from xml.etree import ElementTree as ET

path = Path("android/app/src/main/AndroidManifest.xml")
if not path.exists():
    raise SystemExit("Run flutter create --platforms=android,windows . first")
a = "{http://schemas.android.com/apk/res/android}"
t = "{http://schemas.android.com/tools}"
ET.register_namespace("android", a[1:-1])
ET.register_namespace("tools", t[1:-1])
tree = ET.parse(path)
root = tree.getroot()
for name in (
    "android.permission.INTERNET",
    "android.permission.RECORD_AUDIO",
    "android.permission.WAKE_LOCK",
    "android.permission.FOREGROUND_SERVICE",
    "android.permission.FOREGROUND_SERVICE_MICROPHONE",
    "android.permission.POST_NOTIFICATIONS",
):
    if not any(p.get(a + "name") == name for p in root.findall("uses-permission")):
        ET.SubElement(root, "uses-permission", {a + "name": name})
app = root.find("application")
if app is None:
    raise SystemExit("Missing application in AndroidManifest.xml")
service_name = "de.julianassmann.flutter_background.IsolateHolderService"
service = next((s for s in app.findall("service")
                if s.get(a + "name") == service_name), None)
if service is None:
    service = ET.SubElement(app, "service")
service.set(a + "name", service_name)
service.set(a + "exported", "false")
service.set(a + "foregroundServiceType", "microphone")
service.set(t + "replace", "android:foregroundServiceType")
tree.write(path, encoding="utf-8", xml_declaration=True)
print("Android foreground microphone manifest configured.")
